TZ=Pacific/Kiritimati node --input-type=module -e '
import {checkSms} from "./bot.mjs";
const to=(o={})=>({phone:"+13125550142",timeZone:"America/Chicago",marketingConsent:true,optedOutAt:null,...o});
const m=(t,o)=>checkSms({kind:"marketing",body:"x",to:to(o)},new Date(t));
const rows=[
["ok 08:00 CDT",m("2026-10-23T13:00:00Z"),true],
["before 08:00",m("2026-10-23T12:59:00Z"),"outside_calling_hours"],
["20:59 ok",m("2026-10-24T01:59:00Z"),true],
["21:00 block",m("2026-10-24T02:00:00Z"),"outside_calling_hours"],
["fall-back 07:59 CST",m("2026-11-01T13:59:00Z"),"outside_calling_hours"],
["fall-back 08:00 CST",m("2026-11-01T14:00:00Z"),true],
["opt-out",m("2026-10-23T18:00:00Z",{optedOutAt:"2026-10-01T00:00:00Z"}),"opted_out"],
["no consent",m("2026-10-23T18:00:00Z",{marketingConsent:false}),"no_marketing_consent"],
["missing consent",m("2026-10-23T18:00:00Z",{marketingConsent:undefined}),"no_marketing_consent"],
["bad zone",m("2026-10-23T18:00:00Z",{timeZone:"Mars/Base"}),"invalid_time_zone"],
["txn night opted out",checkSms({kind:"transactional",body:"x",to:to({marketingConsent:false,optedOutAt:"2026-10-01T00:00:00Z"})},new Date("2026-10-23T08:00:00Z")),true],
["bad kind",checkSms({kind:"x",to:to()},new Date()),"invalid_kind"],
];
for(const [n,r,e] of rows){const got=r.allowed?true:r.reason;console.log(got===e?"PASS":"FAIL",n,JSON.stringify(r));}
'

